import{_ as e,a as o,d as r,e as a,f as d,g as s,h as n,i,j as l,k as c,b as u,c as h}from"./chunks/struct-to-json.p_GKhuop.js";import{_ as p,H as g,f as y,i as S}from"./chunks/framework.BIGTPeBz.js";const O=JSON.parse('{"title":"NS_HttpJson","description":"","frontmatter":{},"headers":[],"relativePath":"en/plugins/ns-httpjson.md","filePath":"en/plugins/ns-httpjson.md"}'),b={name:"en/plugins/ns-httpjson.md"};function f(m,t,T,N,q,J){return g(),y("div",null,[...t[0]||(t[0]=[S('<h1 id="ns-httpjson" tabindex="-1">NS_HttpJson <a class="header-anchor" href="#ns-httpjson" aria-label="Permalink to &quot;NS_HttpJson&quot;">​</a></h1><h2 id="plugin-introduction" tabindex="-1">Plugin Introduction <a class="header-anchor" href="#plugin-introduction" aria-label="Permalink to &quot;Plugin Introduction&quot;">​</a></h2><p>NS_HttpJson is a UE Blueprint plugin for <strong>HTTP communication and JSON data processing</strong>. It provides ready-to-use Blueprint nodes for:</p><ul><li>HTTP requests: supports <code>GET</code> / <code>POST</code> / <code>PUT</code> / <code>DELETE</code> / <code>PATCH</code>, with custom headers and Post Data</li><li>File download: progress feedback, save-path control, automatic renaming and timeout control</li><li>File upload: uploads local files as <code>multipart/form-data</code>, with extra form fields and progress feedback</li><li>JSON parsing: extract String / Int / Float / Bool / Array by <code>Key</code> or dot-notation <code>Path</code>, including JSON nested inside strings</li><li>JSON building &amp; editing: serialize a <code>Map</code> / array into JSON in one step, or modify nested values of an existing JSON</li><li>Struct conversion: convert custom structs to/from JSON, including arrays and common types such as <code>FVector</code> / <code>FRotator</code> / <code>FTransform</code></li></ul><p><strong>Module Information</strong></p><table class="ns-module-table"><thead><tr><th>Item</th><th>Value</th></tr></thead><tbody><tr><td>Module Name</td><td><code>NS_HttpJson</code></td></tr><tr><td>Module Type</td><td>Runtime (Loading Phase: PreLoadingScreen)</td></tr><tr><td>Dependencies</td><td>Core, CoreUObject, Engine, Slate, SlateCore, HTTP, Json, JsonUtilities</td></tr><tr><td>Engine Version</td><td>Unreal Engine 5.x (current project based on UE 5.5)</td></tr><tr><td>Supported Platforms</td><td>Win64, Mac, iOS, Android, Linux</td></tr><tr><td>Core Classes</td><td><code>UNS_HttpJsonAsyncAction</code> (HTTP request), <code>UNS_FileUploadAsyncAction</code> (file upload), <code>UNS_FileDownloadAsyncAction</code> (file download)</td></tr><tr><td>Utility Class</td><td><code>UNS_HttpJsonBPLibrary</code> (JSON utility library)</td></tr><tr><td>Blueprint Categories</td><td>NS Http (request / upload / download), NS Json (JSON utility functions)</td></tr></tbody></table><blockquote><p>All HTTP nodes are <strong>async actions</strong>: they return immediately, and results are delivered asynchronously through the output exec pins (<code>On Completed</code>, <code>On Progress</code>) without blocking the game thread.</p></blockquote><h2 id="enumerations" tabindex="-1">Enumerations <a class="header-anchor" href="#enumerations" aria-label="Permalink to &quot;Enumerations&quot;">​</a></h2><h3 id="ens-requesttype" tabindex="-1">ENS_RequestType <a class="header-anchor" href="#ens-requesttype" aria-label="Permalink to &quot;ENS_RequestType&quot;">​</a></h3><p>The request-method selector for <code>NS Send HTTP Request</code>.</p><table tabindex="0"><thead><tr><th>Value</th><th>Description</th></tr></thead><tbody><tr><td>GET</td><td>Retrieves a resource. <code>Post Data</code> is appended to the URL as query parameters (e.g. <code>?a=1&amp;b=2</code>)</td></tr><tr><td>POST</td><td>Submits data. <code>Post Data</code> is serialized into a JSON request body</td></tr><tr><td>PUT</td><td>Updates a resource. <code>Post Data</code> is serialized into a JSON request body</td></tr><tr><td>DELETE</td><td>Deletes a resource. <code>Post Data</code> is appended to the URL as query parameters</td></tr><tr><td>PATCH</td><td>Partially updates a resource. <code>Post Data</code> is serialized into a JSON request body</td></tr></tbody></table><h2 id="http-request-nodes" tabindex="-1">HTTP Request Nodes <a class="header-anchor" href="#http-request-nodes" aria-label="Permalink to &quot;HTTP Request Nodes&quot;">​</a></h2><h3 id="ns-send-http-request-async" tabindex="-1"><span style="color:#41aef5;">NS Send HTTP Request</span> (Async) <a class="header-anchor" href="#ns-send-http-request-async" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;NS Send HTTP Request&lt;/span&gt; (Async)&quot;">​</a></h3><p>A general-purpose HTTP request node supporting all five methods, custom headers and request body data.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>URL</td><td>String</td><td>-</td><td>The full address of the target server, e.g. <code>https://api.example.com/data</code></td></tr><tr><td>Request Type</td><td>ENS_RequestType</td><td>GET</td><td>The request method (see the table above)</td></tr><tr><td>Header</td><td>Map&lt;String, String&gt;</td><td>Empty</td><td>Optional: custom HTTP headers, such as <code>Authorization</code>, <code>Accept</code>, etc.</td></tr><tr><td>Post Data</td><td>Map&lt;String, String&gt;</td><td>Empty</td><td>Query parameters for GET / DELETE; request body data for POST / PUT / PATCH</td></tr><tr><td>Timeout</td><td>Float</td><td>120.0</td><td>Request timeout in seconds; treated as a failure when exceeded</td></tr></tbody></table><p><strong>Outputs (after On Completed)</strong></p><table tabindex="0"><thead><tr><th>Output</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Response Json</td><td>String</td><td>The raw response content returned by the server (usually a JSON string)</td></tr><tr><td>Response Code</td><td>Integer</td><td>The HTTP status code returned by the server (<code>200</code> means success); <code>0</code> on network error / timeout / no response</td></tr></tbody></table><p><strong>Notes</strong></p><ul><li><code>Post Data</code> does not need to be pre-formatted as JSON: for POST / PUT / PATCH the plugin serializes the Map into a JSON object and <strong>automatically sets <code>Content-Type: application/json</code></strong></li><li>For GET / DELETE the <code>Post Data</code> is appended as a <code>key=value&amp;...</code> query string <strong>without URL encoding</strong> — handle special characters yourself</li><li>When the request fails or no valid response is received, <code>Response Json</code> is an empty string and <code>Response Code</code> is <code>0</code>; use that to decide whether the request really succeeded</li><li>Multiple requests can safely run concurrently; every async node reports back independently</li></ul><p><img src="'+e+'" alt="Node - NSSendHttpRequest"></p><hr><h3 id="ns-download-file-async" tabindex="-1"><span style="color:#41aef5;">NS Download File</span> (Async) <a class="header-anchor" href="#ns-download-file-async" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;NS Download File&lt;/span&gt; (Async)&quot;">​</a></h3><p>Downloads a file from the given URL and saves it locally, with progress feedback, relative-path support and timeout control.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Download URL</td><td>String</td><td>-</td><td>The full download URL of the file (HTTP / HTTPS)</td></tr><tr><td>Save Path</td><td>String</td><td>-</td><td>The <strong>directory</strong> to save into. When relative, it is based on the <code>[Project]/Content/</code> folder</td></tr><tr><td>Is Relative Path</td><td>Boolean</td><td>true</td><td>true = <code>Save Path</code> is a relative path; false = absolute path</td></tr><tr><td>Timeout</td><td>Float</td><td>120.0</td><td>Download timeout in seconds</td></tr><tr><td>File Name Alias</td><td>String</td><td>Empty</td><td>Optional: replaces the file name of the downloaded file; leave empty to use the original file name from the URL</td></tr></tbody></table><p><strong>Outputs (after On Completed)</strong></p><table tabindex="0"><thead><tr><th>Output</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Success</td><td>Boolean</td><td>Whether the download finished and the file was written successfully</td></tr><tr><td>Saved File Path</td><td>String</td><td>The full path where the file was finally saved</td></tr><tr><td>File Name</td><td>String</td><td>The final file name (the alias may have been applied)</td></tr><tr><td>Progress Ratio</td><td>Float</td><td>Progress ratio, <code>1.0</code> when complete</td></tr></tbody></table><p><strong>Outputs (fired repeatedly by On Progress)</strong></p><table tabindex="0"><thead><tr><th>Output</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Progress Ratio</td><td>Float</td><td>Current download progress ratio (0.0 ~ 1.0)</td></tr><tr><td>Bytes Received</td><td>Integer64</td><td>Bytes received so far</td></tr><tr><td>Total Bytes</td><td>Integer64</td><td>Total size in bytes; <code>-1</code> when the server sends no <code>Content-Length</code> (the progress is then an estimate)</td></tr></tbody></table><p><strong>Notes</strong></p><ul><li>The file name is taken from the last segment of the URL path by default (query parameters are stripped); if the URL has no file name at the end, <code>downloaded_file</code> is used</li><li><code>File Name Alias</code> only replaces the base name and <strong>keeps the original extension</strong> (e.g. <code>a.zip</code> with alias <code>my</code> becomes <code>my.zip</code>); if the original file has no extension the alias is used as-is</li><li>The plugin creates missing save directories automatically (including nested levels)</li><li>Unlike upload, download only checks whether a <strong>valid response</strong> was received and does not validate a 2xx status code — a 404 / 500 body is still saved, so validate it against your business rules</li><li>The file is fully buffered in memory before being written to disk, so it is not suitable for extremely large files</li></ul><p><img src="'+o+'" alt="Node - NSDownloadFile"></p><hr><h3 id="ns-upload-file-async" tabindex="-1"><span style="color:#41aef5;">NS Upload File</span> (Async) <a class="header-anchor" href="#ns-upload-file-async" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;NS Upload File&lt;/span&gt; (Async)&quot;">​</a></h3><p>Uploads a local file as <code>multipart/form-data</code>, with progress tracking, custom headers and extra form fields.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Upload URL</td><td>String</td><td>-</td><td>The endpoint on the server that accepts the upload</td></tr><tr><td>File Path</td><td>String</td><td>-</td><td>The local file path to upload; a relative path is based on the <code>[Project]/Content/</code> folder</td></tr><tr><td>File Field Name</td><td>String</td><td>Empty</td><td>The form field name for the file; defaults to <code>file</code> when empty</td></tr><tr><td>Header</td><td>Map&lt;String, String&gt;</td><td>Empty</td><td>Optional: custom HTTP headers (e.g. an auth token)</td></tr><tr><td>Post Data</td><td>Map&lt;String, String&gt;</td><td>Empty</td><td>Optional: <strong>extra form fields</strong> sent with the request (e.g. user ID, file description), written before the file field</td></tr><tr><td>Is Relative Path</td><td>Boolean</td><td>true</td><td>true = <code>File Path</code> is a relative path; false = absolute path</td></tr><tr><td>Timeout</td><td>Float</td><td>120.0</td><td>Upload timeout in seconds</td></tr></tbody></table><p><strong>Outputs (after On Completed)</strong></p><table tabindex="0"><thead><tr><th>Output</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Success</td><td>Boolean</td><td>Whether the upload succeeded (2xx response code)</td></tr><tr><td>Response Content</td><td>String</td><td>The raw response returned by the server (usually a JSON feedback)</td></tr><tr><td>Response Code</td><td>Integer</td><td>The HTTP status code returned by the server</td></tr><tr><td>Progress Ratio</td><td>Float</td><td>Progress ratio, <code>1.0</code> when complete</td></tr></tbody></table><p><strong>Outputs (fired repeatedly by On Progress)</strong></p><table tabindex="0"><thead><tr><th>Output</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Progress Ratio</td><td>Float</td><td>Current upload progress ratio (0.0 ~ 1.0)</td></tr><tr><td>Bytes Sent</td><td>Integer64</td><td>Bytes sent so far</td></tr><tr><td>Total Bytes</td><td>Integer64</td><td>Total bytes to upload</td></tr></tbody></table><p><strong>Notes</strong></p><ul><li>Unlike download, an upload is considered successful <strong>only when the server returns a 2xx status code</strong>; otherwise <code>Success = false</code> and <code>Response Content</code> holds the error returned by the server</li><li>If the file does not exist or cannot be read, the node reports back immediately: <code>Success = false</code>, <code>Response Code = 0</code>, with the reason in <code>Response Content</code> (e.g. <code>File not found: xxx</code>)</li><li>The file field&#39;s <code>Content-Type</code> is fixed to <code>application/octet-stream</code>; the multipart boundary is generated automatically by the plugin</li><li>The upload method is always <code>POST</code></li></ul><p><img src="'+r+'" alt="Node - NSUploadFile"></p><h2 id="json-reading-nodes" tabindex="-1">JSON Reading Nodes <a class="header-anchor" href="#json-reading-nodes" aria-label="Permalink to &quot;JSON Reading Nodes&quot;">​</a></h2><p>All JSON reading nodes are <strong>pure functions (no exec pins)</strong> and can be used directly as value getters in Blueprints — pass in the JSON string and read the result.</p><p>They fall into two groups:</p><ul><li><strong>Value nodes</strong>: read a <code>Key</code> from the <strong>top-level object</strong> of the JSON, best for flat structures</li><li><strong>Path nodes</strong>: use a dot-notation <code>Path</code> (e.g. <code>user.info.name</code>) to reach nested fields at any depth</li></ul><blockquote><p>Both groups also handle JSON nested inside strings — a field value formatted as <code>&quot;{...}&quot;</code> / <code>&quot;[...]&quot;</code> can still be traversed further.</p></blockquote><h3 id="ns-json-value-to-string-int-float-bool" tabindex="-1"><span style="color:#41aef5;">NS Json Value To String / Int / Float / Bool</span> <a class="header-anchor" href="#ns-json-value-to-string-int-float-bool" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;NS Json Value To String / Int / Float / Bool&lt;/span&gt;&quot;">​</a></h3><p>Extracts the value for a <code>Key</code> from the JSON object and converts it to the target type.</p><p><strong>Shared inputs</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Json String</td><td>String</td><td>The JSON string to parse (usually from <code>Response Json</code> of <code>NS Send HTTP Request</code>)</td></tr><tr><td>Key</td><td>String</td><td>The target key, matched at the top level only. E.g. for <code>{&quot;user_id&quot;: 123}</code> use <code>user_id</code></td></tr></tbody></table><p><strong>Return values</strong></p><table tabindex="0"><thead><tr><th>Node</th><th>Return type</th><th>Description</th></tr></thead><tbody><tr><td>NS Json Value To String</td><td>String</td><td>Strings pass through unchanged; numbers / booleans become strings; objects / arrays become compact JSON strings</td></tr><tr><td>NS Json Value To Int</td><td>Integer</td><td>Rounds the number to an integer</td></tr><tr><td>NS Json Value To Float</td><td>Float</td><td>Returns the number</td></tr><tr><td>NS Json Value To Bool</td><td>Boolean</td><td>Returns the boolean</td></tr></tbody></table><p><strong>Note</strong>: when the key is missing, the JSON fails to parse, or the type does not match, String returns an empty string, Int returns <code>0</code>, Float returns <code>0.0</code> and Bool returns <code>false</code>.</p><p><img src="'+a+'" alt="Node group - NSJsonValueToType"></p><hr><h3 id="ns-json-path-to-string-int-float-bool" tabindex="-1"><span style="color:#41aef5;">NS Json Path To String / Int / Float / Bool</span> <a class="header-anchor" href="#ns-json-path-to-string-int-float-bool" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;NS Json Path To String / Int / Float / Bool&lt;/span&gt;&quot;">​</a></h3><p>Deep JSON data extraction: use a dot-notation <code>Path</code> to reach nested structures directly, without multi-step parsing.</p><p><strong>Shared inputs</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Json String</td><td>String</td><td>The JSON string to parse</td></tr><tr><td>Path</td><td>String</td><td>A dot-notation path. E.g. for <code>{&quot;user&quot;:{&quot;info&quot;:{&quot;name&quot;:&quot;Test&quot;}}}</code>, use <code>user.info.name</code> to get the name</td></tr></tbody></table><p><strong>Return values</strong> are the same as the Value group (String / Int / Float / Bool), depending on the node you use.</p><p><strong>Note</strong>: when any segment of the path is missing, is not an object, or cannot be traversed, the node returns the default value of the target type (<code>&quot;&quot;</code> / <code>0</code> / <code>0.0</code> / <code>false</code>); the path can also pass through JSON objects nested inside strings.</p><p><img src="'+d+'" alt="Node group - NSJsonPathToType"></p><hr><h3 id="ns-json-value-path-to-array" tabindex="-1"><span style="color:#41aef5;">NS Json Value / Path To Array</span> <a class="header-anchor" href="#ns-json-value-path-to-array" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;NS Json Value / Path To Array&lt;/span&gt;&quot;">​</a></h3><p>Extracts a JSON array into a Blueprint array variable. Six nodes are provided:</p><table tabindex="0"><thead><tr><th>Node</th><th>Inputs</th><th>Return type</th></tr></thead><tbody><tr><td>NS Json Value To Array (String)</td><td>Json String + Key</td><td>String array</td></tr><tr><td>NS Json Value To Array (Int)</td><td>Json String + Key</td><td>Integer array</td></tr><tr><td>NS Json Value To Array (Float)</td><td>Json String + Key</td><td>Float array</td></tr><tr><td>NS Json Path To Array (String)</td><td>Json String + Path</td><td>String array</td></tr><tr><td>NS Json Path To Array (Int)</td><td>Json String + Path</td><td>Integer array</td></tr><tr><td>NS Json Path To Array (Float)</td><td>Json String + Path</td><td>Float array</td></tr></tbody></table><p><strong>Details</strong></p><ul><li>Works with real arrays (<code>&quot;scores&quot;:[10,20,30]</code>) as well as arrays stored as strings (<code>&quot;scores&quot;:&quot;[10,20,30]&quot;</code>)</li><li>Elements are converted automatically: e.g. the Int nodes turn numbers, strings (<code>Atoi</code>) and booleans (true = 1) into integers</li><li>If the key / path is missing, is not an array, or a conversion fails, an <strong>empty array</strong> is returned (no error)</li></ul><p><img src="'+s+'" alt="Node group - NSJsonValuePathToArray"></p><h2 id="json-building-nodes" tabindex="-1">JSON Building Nodes <a class="header-anchor" href="#json-building-nodes" aria-label="Permalink to &quot;JSON Building Nodes&quot;">​</a></h2><h3 id="ns-map-to-json" tabindex="-1"><span style="color:#41aef5;">NS Map To Json</span> <a class="header-anchor" href="#ns-map-to-json" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;NS Map To Json&lt;/span&gt;&quot;">​</a></h3><p>Serializes a Blueprint <code>Map&lt;String, String&gt;</code> into a JSON object string — the core tool for building HTTP request bodies.</p><table tabindex="0"><thead><tr><th>Parameter / Return</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Map</td><td>Map&lt;String, String&gt;</td><td>Keys become JSON field names, values become field values</td></tr><tr><td>Return Value</td><td>String</td><td>The serialized JSON string</td></tr></tbody></table><p><strong>Automatic nesting rules</strong></p><p>If a Map value is itself valid <code>{...}</code> (object) or <code>[...]</code> (array) text, it is parsed automatically into a nested object / array; otherwise it is stored as a plain string value.</p><p>For example, feeding the output of <strong>NS Int Array To Json</strong> (<code>[10,20,30]</code>) as a Map value produces nested JSON like <code>{&quot;user_id&quot;:&quot;101&quot;,&quot;scores&quot;:[10,20,30]}</code>.</p><blockquote><p>Since <code>TMap</code> is unordered under the hood, the <strong>field order of the output JSON is not guaranteed</strong> to match insertion order — do not rely on ordering (JSON semantics do not depend on it either).</p></blockquote><p><img src="'+n+'" alt="Node - NSMapToJson"></p><hr><h3 id="ns-string-int-float-array-to-json" tabindex="-1"><span style="color:#41aef5;">NS String / Int / Float Array To Json</span> <a class="header-anchor" href="#ns-string-int-float-array-to-json" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;NS String / Int / Float Array To Json&lt;/span&gt;&quot;">​</a></h3><p>Quickly serializes primitive-type arrays into JSON array strings. Three nodes are provided:</p><table tabindex="0"><thead><tr><th>Node</th><th>Input type</th><th>Returns</th><th>Example output</th></tr></thead><tbody><tr><td>NS String Array To Json</td><td>String array</td><td>String</td><td><code>[&quot;item1&quot;,&quot;item2&quot;]</code></td></tr><tr><td>NS Int Array To Json</td><td>Integer array</td><td>String</td><td><code>[10,20,30]</code></td></tr><tr><td>NS Float Array To Json</td><td>Float array</td><td>String</td><td><code>[1.5,2.5]</code></td></tr></tbody></table><p><strong>Note</strong>: elements of a String array that look like <code>{...}</code> / <code>[...]</code> text are parsed into nested objects / arrays as well. The serialized result is commonly used as a sub-value (string) inside the Map of <strong>NS Map To Json</strong> to build complex request bodies.</p><p><img src="'+i+'" alt="Node group - NSArrayToJson"></p><hr><h3 id="ns-json-array-to-string-array" tabindex="-1"><span style="color:#41aef5;">NS Json Array To String Array</span> <a class="header-anchor" href="#ns-json-array-to-string-array" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;NS Json Array To String Array&lt;/span&gt;&quot;">​</a></h3><p>Converts a <strong>pure array string without keys</strong> into a String array, for interfaces that return values such as <code>[&quot;key1&quot;,&quot;key2&quot;,...]</code>.</p><table tabindex="0"><thead><tr><th>Parameter / Return</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Json Array String</td><td>String</td><td>Must be a valid JSON array wrapped in <code>[</code> <code>]</code>, e.g. <code>[&quot;apple&quot;,&quot;banana&quot;]</code></td></tr><tr><td>Return Value</td><td>String array</td><td>The converted string array</td></tr></tbody></table><p><strong>Note</strong>: number, boolean, nested object / array elements are also converted to strings; if the input cannot be parsed at all, the original input is returned as a single-element array.</p><p><img src="'+l+'" alt="Node - NSJsonArrayToStringArray"></p><h2 id="json-editing-nodes" tabindex="-1">JSON Editing Nodes <a class="header-anchor" href="#json-editing-nodes" aria-label="Permalink to &quot;JSON Editing Nodes&quot;">​</a></h2><h3 id="ns-set-json-value-string-int-float-bool" tabindex="-1"><span style="color:#41aef5;">NS Set Json Value (String / Int / Float / Bool)</span> <a class="header-anchor" href="#ns-set-json-value-string-int-float-bool" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;NS Set Json Value (String / Int / Float / Bool)&lt;/span&gt;&quot;">​</a></h3><p>Sets (adds or overwrites) one field in an existing JSON and returns the modified full JSON string. Four nodes are provided, distinguished by the type of the <code>Value</code> parameter.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Json String</td><td>String</td><td>The original JSON string</td></tr><tr><td>Key</td><td>String</td><td>The field key; <strong>supports dot-notation paths</strong>, e.g. <code>data.name</code> modifies a nested field</td></tr><tr><td>Value</td><td>String / Integer / Float / Boolean</td><td>The value to write, depending on the node type</td></tr><tr><td>Return Value</td><td>String</td><td>The modified full JSON string</td></tr></tbody></table><p><strong>Notes</strong></p><ul><li><code>Key</code> supports dot-notation paths: missing intermediate nodes are <strong>created as objects automatically</strong>; if an intermediate node is JSON nested inside a string, it is parsed, modified and written back as a string</li><li>If the JSON fails to parse, the input <code>Json String</code> is returned unchanged, so no data is lost</li></ul><p><img src="'+c+'" alt="Node group - NSSetJsonValue"></p><h2 id="struct-conversion-nodes" tabindex="-1">Struct Conversion Nodes <a class="header-anchor" href="#struct-conversion-nodes" aria-label="Permalink to &quot;Struct Conversion Nodes&quot;">​</a></h2><p>The struct-to-JSON conversion nodes are reflection-based and work well with HTTP responses for typed &quot;JSON → struct variable&quot; reads.</p><p>There are four nodes, grouped by <strong>conversion direction</strong>:</p><ul><li><strong>Parsing direction (JSON → Struct)</strong>: fills struct variables from JSON — <code>NS Json To Struct</code> (single object), <code>NS Json To Struct Array</code> (array of objects)</li><li><strong>Serialization direction (Struct → JSON)</strong>: outputs struct variables as JSON strings — <code>NS Struct To Json</code> (single struct), <code>NS Struct Array To Json</code> (array of structs)</li></ul><p>Both directions share the same reflection rules:</p><ul><li>Field names match the names shown in the editor for the struct (case-sensitive); properties without a matching JSON field keep their original value</li><li>Bool / Int / Int64 / Float / String, nested structs, one-dimensional basic arrays are supported, plus <code>FVector</code> / <code>FRotator</code> / <code>FTransform</code></li></ul><h3 id="parsing-direction-json-→-struct" tabindex="-1">Parsing Direction: JSON → Struct <a class="header-anchor" href="#parsing-direction-json-→-struct" aria-label="Permalink to &quot;Parsing Direction: JSON → Struct&quot;">​</a></h3><p>Parse JSON returned by the server straight into struct variables, avoiding per-field extraction. Both nodes <strong>modify the target variable in place (they have exec pins)</strong>; when the JSON is invalid or fields are missing the original data stays unchanged, so they are safe for tolerant reads.</p><h4 id="ns-json-to-struct" tabindex="-1"><span style="color:#41aef5;">NS Json To Struct</span> <a class="header-anchor" href="#ns-json-to-struct" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;NS Json To Struct&lt;/span&gt;&quot;">​</a></h4><p>Fills a struct variable from a single JSON object string, matching fields by name.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Json String</td><td>String</td><td>The JSON object string to parse</td></tr><tr><td>In Out Struct</td><td>Any struct</td><td>The target struct variable, filled after the call</td></tr></tbody></table><blockquote><p>In JSON, <code>FVector</code> / <code>FRotator</code> / <code>FTransform</code> can be object forms (<code>{X,Y,Z}</code> / <code>{Pitch,Yaw,Roll}</code>) or UE string forms.</p></blockquote><h4 id="ns-json-to-struct-array" tabindex="-1"><span style="color:#41aef5;">NS Json To Struct Array</span> <a class="header-anchor" href="#ns-json-to-struct-array" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;NS Json To Struct Array&lt;/span&gt;&quot;">​</a></h4><p>Parses a JSON array string and fills a struct-array variable.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Json String</td><td>String</td><td>The JSON array string to parse</td></tr><tr><td>In Out Struct Array</td><td>Struct array</td><td>The target struct-array variable, filled after the call</td></tr></tbody></table><blockquote><p>Array elements can be JSON objects or JSON objects nested inside strings; the array stays unchanged if parsing fails.</p></blockquote><p><img src="'+u+'" alt="Node group - NSJsonToStruct / NSJsonToStructArray"></p><hr><h3 id="serialization-direction-struct-→-json" tabindex="-1">Serialization Direction: Struct → JSON <a class="header-anchor" href="#serialization-direction-struct-→-json" aria-label="Permalink to &quot;Serialization Direction: Struct → JSON&quot;">​</a></h3><p>Serializes struct variables into JSON, commonly used to pack config / result objects into request bodies before uploading. Both nodes are <strong>pure functions</strong>. On failure they return <code>{}</code> / <code>[]</code> respectively.</p><h4 id="ns-struct-to-json" tabindex="-1"><span style="color:#41aef5;">NS Struct To Json</span> <a class="header-anchor" href="#ns-struct-to-json" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;NS Struct To Json&lt;/span&gt;&quot;">​</a></h4><p>Serializes a single struct into a JSON object string.</p><table tabindex="0"><thead><tr><th>Parameter / Return</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>In Struct</td><td>Any struct</td><td>The struct variable to serialize</td></tr><tr><td>Return Value</td><td>String</td><td>The JSON string; returns <code>{}</code> on failure</td></tr></tbody></table><blockquote><p><code>FVector</code> / <code>FRotator</code> / <code>FTransform</code> are emitted as UE <code>ToString</code> strings; nested structs are emitted as JSON objects.</p></blockquote><h4 id="ns-struct-array-to-json" tabindex="-1"><span style="color:#41aef5;">NS Struct Array To Json</span> <a class="header-anchor" href="#ns-struct-array-to-json" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;NS Struct Array To Json&lt;/span&gt;&quot;">​</a></h4><p>Serializes an array of structs into a JSON array string.</p><table tabindex="0"><thead><tr><th>Parameter / Return</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>In Struct Array</td><td>Struct array</td><td>The elements must be structs</td></tr><tr><td>Return Value</td><td>String</td><td>The JSON array string; returns <code>[]</code> on failure</td></tr></tbody></table><p><img src="'+h+'" alt="Node group - NSStructToJson / NSStructArrayToJson"></p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ol><li><p><strong>Requests &amp; callbacks</strong></p><ul><li><code>NS Send HTTP Request</code> calls back <strong>exactly once</strong> for success / failure: a valid response triggers the callback with its status code; network errors / timeouts call back with an empty response and code <code>0</code></li><li>An upload succeeds only with a <code>2xx</code> status code; a download only checks whether a response body was received and does not validate the status code</li><li>All three HTTP nodes are async actions registered with the GameInstance, so they can safely run concurrently</li></ul></li><li><p><strong>Post Data / request body</strong></p><ul><li>For GET / DELETE the <code>Post Data</code> becomes a query string (appended with <code>&amp;</code> when the URL already contains <code>?</code>), <strong>without URL encoding</strong></li><li>For POST / PUT / PATCH the <code>Post Data</code> is serialized into a JSON request body and <code>Content-Type: application/json</code> is set automatically (it overrides the same-named preset value in <code>Header</code>)</li></ul></li><li><p><strong>Path meaning</strong></p><ul><li>When <code>Is Relative Path</code> is checked for upload / download, <code>File Path</code> / <code>Save Path</code> are relative to the <code>[Project]/Content/</code> directory (<code>ProjectContentDir</code>)</li><li>The download <code>Save Path</code> is the target <strong>directory</strong> (created automatically if missing); the file name comes from the URL or <code>File Name Alias</code></li></ul></li><li><p><strong>JSON extraction</strong></p><ul><li><code>NS Json Value To X</code> reads only top-level keys, while <code>NS Json Path To X</code> traverses deep paths with dot notation; both handle JSON nested inside strings</li><li>Extraction never fails hard: String returns an empty string, Int returns <code>0</code>, Float returns <code>0.0</code>, Bool returns <code>false</code>, arrays return empty — confirm the field exists first</li></ul></li><li><p><strong>Map to JSON</strong></p><ul><li><code>TMap</code> is unordered, so the field order of <code>NS Map To Json</code> output is not guaranteed; for order-dependent servers prefer the struct conversion nodes</li><li>Generate an array text with <code>[Type] Array To Json</code> and use it as a Map value, then run <code>NS Map To Json</code> to build nested structures — the recommended way to assemble complex request bodies</li></ul></li><li><p><strong>Struct conversion</strong></p><ul><li>Field names match the names shown in the editor, case-sensitive; mark your structs with <code>BlueprintType</code> so they can be created as variables</li><li><code>NS Json To Struct</code> / <code>NS Json To Struct Array</code> keep the original data unchanged when JSON parsing fails, so they are safe for tolerant reads</li></ul></li></ol>',128)])])}const x=p(b,[["render",f]]);export{O as __pageData,x as default};
